def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    beds = image_patch.find("bed")
    bears = image_patch.find("bear")

    if not beds or not bears:
        return image_patch

    bed_centers = [(b.left + b.right) / 2 for b in beds]
    bear_centers = [(b.left + b.right) / 2 for b in bears]

    closest_bed = min(beds, key=lambda b: abs((b.left + b.right) / 2 - bear_centers[0]))
    closest_bed_idx = bed_centers.index(closest_bed.horizontal_center)

    if closest_bed_idx == 0:
        return beds[closest_bed_idx]
    elif closest_bed_idx == len(beds) - 1:
        return beds[closest_bed_idx]
    else:
